        # cells: list of (i,j,v) on one line, contiguous and >=2 distinct colors
        if len(cells)<2: return False
        (i0,j0,_),*rest=cells
        return all((abs(i-i0)<=1 and j==j0) or (abs(j-j0)<=1 and i==i0) for i,j,_ in cells) \
            and len({v for _,_,v in cells})>=2
    bar=None
    for j in range(W):
