        runs=[]
        for c in cl:
            if runs and c[0]==runs[-1][-1][0]+1: runs[-1].append(c)
            else: runs.append([c])
        for r in runs:
            if len(r)>=2 and len({v for _,_,v in r})>=2: bar=r; break
